-- gloss pronunciation table update
-- Import: turso db shell gloss < pronunciation-update.sql

DROP TABLE IF EXISTS pronunciation;
CREATE TABLE "pronunciation"(
    lemma_id INTEGER NOT NULL REFERENCES lemma(id),
    variety TEXT NOT NULL,
    ipa TEXT NOT NULL,
    respelling TEXT NOT NULL,
    respelling_syll TEXT NOT NULL,
    source TEXT NOT NULL,
    PRIMARY KEY(lemma_id, variety, source, ipa));
CREATE INDEX idx_pronunciation_lemma ON pronunciation(lemma_id);
INSERT OR REPLACE INTO meta(key, value) VALUES('pronunciation_sources','{"oewn_xml": "english-wordnet-2024.xml.gz", "cmudict": "https://raw.githubusercontent.com/cmusphinx/cmudict/master/cmudict.dict", "respelling": "attacktive/ipa-to-pronunciation-respelling (MIT), ported to data/respell.py"}');
INSERT OR REPLACE INTO meta(key, value) VALUES('pronunciation_counts','{"rows": 62364, "oewn_rows": 43628, "cmudict_rows": 18736, "lemmas_covered": 51275}');
